class WallQrPrintPageTest(TestCase):
    """Standalone /stock/wall-qr/print/ page (2026-07-23, live report: printing
    the QR straight from payment_settings.html produced 4 blank pages then a
    tiny QR on the 5th — the visibility/absolute-position trick used there
    anchored the QR box to a positioned ancestor deep in a very long page
    instead of the page's top). The standalone page must render one clean
    page with nothing else on it."""

    def setUp(self):
        self.biz = Business.objects.create(name='Wall QR Print Biz', has_kitchen=True)
        self.owner = User.objects.create_user(username='wallqrprint_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(username='wallqrprint_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')

    def test_owner_can_view_print_page(self):
        self.client.force_login(self.owner)
        resp = self.client.get('/stock/wall-qr/print/')
        self.assertEqual(resp.status_code, 200)
        self.assertIn(b'Scan To View Your Bill', resp.content)
        # escapejs renders '-' as the unicode escape - inside the JS string.
        self.assertIn(f'/bar/find\\u002Dtab/{self.biz.id}/'.encode(), resp.content)

    def test_header_and_footer_both_present(self):
        """User's explicit ask: bold text at both the top AND bottom of the page."""
        self.client.force_login(self.owner)
        resp = self.client.get('/stock/wall-qr/print/')
        self.assertEqual(resp.content.count(b'Scan To View Your Bill'), 2)

    def test_print_param_triggers_auto_print(self):
        self.client.force_login(self.owner)
        resp = self.client.get('/stock/wall-qr/print/?print=1')
        self.assertIn(b'window.print()', resp.content)
        # Without ?print=1, no auto-print call should be emitted.
        resp2 = self.client.get('/stock/wall-qr/print/')
        self.assertNotIn(b'setTimeout(function () { window.print(); }, 500);', resp2.content)

    def test_staff_redirected_away(self):
        self.client.force_login(self.staff)
        resp = self.client.get('/stock/wall-qr/print/')
        self.assertEqual(resp.status_code, 302)

    def test_unauthenticated_redirected_to_login(self):
        resp = self.client.get('/stock/wall-qr/print/')
        self.assertEqual(resp.status_code, 302)
        self.assertIn('/login', resp.url)

    def test_payment_settings_links_to_print_page(self):
        self.client.force_login(self.owner)
        resp = self.client.get('/business/payment-settings/')
        self.assertIn(b'/stock/wall-qr/print/?print=1', resp.content)


class CrossCounterReceiptLinkingTest(TestCase):
    """Fix (2026-07-16): a customer's running tab must resolve to ONE shared receipt/PIN
    regardless of which counter (Bar, Kitchen, Quick Sell) rings up their next item.

    Root cause of the gap: each counter had its own hand-copied version of the
    master-receipt lookup and they'd drifted — Bar Board checked everything
    (own receipt, linked_tab_ids, kitchen tabs, any same-day receipt), Kitchen only
    checked Bar (not Quick Sell), and Quick Sell's tab flow checked nothing beyond its
    own tab. core/tab_receipts.py:resolve_master_receipt() is now the single source of
    truth all three call. These tests cover the two directions that were previously
    broken (Bar/Kitchen tab exists first, Quick Sell rings up second) plus a direct
    unit test of the priority chain."""

    def setUp(self):
        self.biz = Business.objects.create(name='Cross Counter Biz')
        self.bar_store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='xcounter_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.bar_store, description='XCounter Soda',
            material_no='XCTR-01', unit='pcs', selling_price=Decimal('100'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('20'),
        )
        self.client.force_login(self.owner)

    def _make_tab_with_receipt(self, source, customer_name='Cross Patron'):
        tab = BarTab.objects.create(
            business=self.biz, customer_name=customer_name, status='OPEN', source=source,
        )
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='credit',
        )
        BarTabEntry.objects.create(tab=tab, transaction=txn, description='XCounter Soda', amount=Decimal('100'))
        rcpt = Receipt.issue(
            business=self.biz, lines=[{'name': 'XCounter Soda', 'qty': 1, 'subtotal': 100}],
            payment_method='tab', customer_name=customer_name, meta={'tab_id': tab.id},
        )
        return tab, rcpt

    def test_resolver_finds_own_receipt_first(self):
        from core.tab_receipts import resolve_master_receipt
        tab, rcpt = self._make_tab_with_receipt('bar')
        found, freshly_linked = resolve_master_receipt(self.biz, tab)
        self.assertEqual(found.id, rcpt.id)
        self.assertFalse(freshly_linked)

    def test_resolver_links_to_another_open_tabs_receipt_any_source(self):
        from core.tab_receipts import resolve_master_receipt
        bar_tab, bar_rcpt = self._make_tab_with_receipt('bar')
        qs_tab = BarTab.objects.create(
            business=self.biz, customer_name='Cross Patron', status='OPEN', source='qs',
        )
        found, freshly_linked = resolve_master_receipt(self.biz, qs_tab)
        self.assertEqual(found.id, bar_rcpt.id)
        self.assertTrue(freshly_linked)
        bar_rcpt.refresh_from_db()
        self.assertIn(qs_tab.id, bar_rcpt.meta.get('linked_tab_ids', []))

    def test_resolver_falls_back_to_any_todays_receipt_for_customer(self):
        from core.tab_receipts import resolve_master_receipt
        # A receipt with no live OPEN tab attached (e.g. a settled/standalone credit sale)
        rcpt = Receipt.issue(
            business=self.biz, lines=[{'name': 'XCounter Soda', 'qty': 1, 'subtotal': 100}],
            payment_method='credit', customer_name='Cross Patron',
        )
        new_tab = BarTab.objects.create(
            business=self.biz, customer_name='Cross Patron', status='OPEN', source='kitchen',
        )
        found, freshly_linked = resolve_master_receipt(self.biz, new_tab)
        self.assertEqual(found.id, rcpt.id)
        self.assertTrue(freshly_linked)

    def test_quick_sell_tab_links_into_existing_bar_tab_receipt(self):
        """The actual regression: previously Quick Sell's tab flow never looked for a
        pre-existing Bar tab receipt — it always issued a second, separate receipt."""
        import json
        bar_tab, bar_rcpt = self._make_tab_with_receipt('bar', customer_name='QS Link Patron')
        cart = json.dumps([{'id': self.item.id, 'qty': 1, 'price': 100}])
        self.client.post('/quick-sell/', {
            'cart': cart, 'payment_method': 'tab', 'recipient': 'QS Link Patron',
        })
        qs_tab = BarTab.objects.filter(
            business=self.biz, customer_name='QS Link Patron', source='qs',
        ).first()
        self.assertIsNotNone(qs_tab)
        self.assertEqual(
            Receipt.objects.filter(business=self.biz, customer_name__iexact='QS Link Patron').count(),
            1,
            'Quick Sell must reuse the existing Bar tab receipt, not create a second one',
        )
        bar_rcpt.refresh_from_db()
        self.assertIn(qs_tab.id, bar_rcpt.meta.get('linked_tab_ids', []))


class NetProfitWastageDeductionTest(TestCase):
    """K8 audit (Task 1, deferred): regression-locks the current, intentional net_profit
    formula — wastage_loss must be deducted exactly once (added in the 2026-07-13 sprint
    to fix wastage being invisible to P&L). A future change must not re-break this."""

    def setUp(self):
        self.biz = Business.objects.create(name='K8 PnL Biz')
        self.store = Store.objects.create(business=self.biz, name='Main')
        self.owner = User.objects.create_user(username='k8_pnl_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='K8 Item', unit='Pcs',
            material_no='K8-ITEM-01', selling_price=Decimal('100'), cost_price=Decimal('40'),
        )

    def test_wastage_reduces_net_profit_but_not_gross_profit(self):
        today = timezone.localdate()
        # One sale: revenue 100, cost 40 -> gross profit 60
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'),
            payment_method='cash', date=today,
        )
        # One wastage event: 2 units at cost 40 each = 80 loss, zero revenue impact
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Wastage',
            qty=Decimal('-2'), date=today,
        )
        self.client.force_login(self.owner)
        resp = self.client.get('/analytics/?period=30')
        self.assertEqual(resp.status_code, 200)
        ctx = resp.context
        self.assertEqual(ctx['cur_profit'], 60.0, 'Wastage must not appear in gross profit (COGS-of-sold only)')
        self.assertEqual(ctx['wastage_loss'], 80.0)
        self.assertEqual(
            ctx['net_profit'], ctx['cur_profit'] - ctx['total_losses'],
            'net_profit must deduct wastage_loss exactly once via total_losses',
        )
        self.assertEqual(ctx['net_profit'], -20.0)


class TransactionLossValueFixTest(TestCase):
    """2026-08-11 live report (Roy, with screenshots): the Analytics "Hasara/
    Losses" tile showed "Voids: 10,020,600" on a business doing ~KES 150k of
    revenue for the period — an obviously impossible figure. Root cause:
    analytics_views.py's wastage_loss/void_loss/owner_drawings_cost each
    reimplemented a naive `abs(qty) * item.cost_price` formula instead of
    reusing Transaction.cost()'s own keg/bunch/batch/preset-aware
    proportional logic. For a keg pour specifically, qty is stored in ml
    while item.cost_price is priced per WHOLE KEG (thousands of KES) — a
    single voided ~500ml pour naively priced as `500 * cost_per_keg`
    inflates by roughly 1000x, more than enough to produce a multi-million-
    shilling phantom loss from a handful of voided pours. Fixed by
    extracting Transaction.cost()'s branch logic into
    _stock_movement_cost(), reused by both cost() (Issue only, unchanged)
    and the new loss_value() (Wastage/OwnerConsumption)."""

    def setUp(self):
        _make_keg_setup(self, 'lossval')

    def test_plain_item_wastage_unchanged(self):
        """Regression lock — the ordinary, most common case (no keg/bunch/
        batch/preset FK) must compute exactly as before."""
        item = Item.objects.create(
            business=self.biz, store=self.store, description='Plain Item',
            material_no='LV-PLAIN-01', selling_price=Decimal('100'), cost_price=Decimal('40'),
        )
        txn = Transaction.objects.create(
            business=self.biz, item=item, type='Wastage', qty=Decimal('-2'),
        )
        self.assertEqual(txn.loss_value(), 80.0)

    def test_voided_keg_pour_is_small_proportional_value_not_millions(self):
        """The literal reported bug: a voided keg pour must cost a few
        shillings (proportional to the barrel's own cost/target), never
        qty(ml) * item.cost_price(per-keg, thousands of KES)."""
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-500'), sale_amount=Decimal('50'),
            payment_method='void', keg_barrel=self.barrel,
        )
        # Naive (buggy) formula would give abs(-500) * 12000 = 6,000,000.
        naive_buggy_value = abs(float(txn.qty)) * float(self.item.cost_price)
        self.assertGreater(naive_buggy_value, 1_000_000)
        # Correct: sale_amount(50) * barrel.cost_price(12000) / barrel.target_revenue(18000)
        expected = 50.0 * 12000.0 / 18000.0
        self.assertAlmostEqual(txn.cost(), expected, places=2)
        self.assertLess(txn.cost(), 100)  # sane, small, proportional value

    def test_produce_bunch_discard_uses_bunch_cost_not_item_cost(self):
        from core.models import ProduceBunch
        item = Item.objects.create(
            business=self.biz, store=self.store, description='Sukuma',
            material_no='LV-BUNCH-01', is_produce=True, produce_mode='BUNCH',
            selling_price=Decimal('10'), cost_price=Decimal('9999'),  # deliberately wrong/stale
        )
        bunch = ProduceBunch.objects.create(
            business=self.biz, item=item, size='MEDIUM',
            cost_price=Decimal('50'), target_revenue=Decimal('80'),
            status='OPEN',
        )
        bunch.record_sale(Decimal('20'), 'cash')  # 20 of 80 sold
        txn = bunch.discard('Wilted')
        self.assertIsNotNone(txn)
        # leftover = 60/80 of the bunch remaining -> 0.75 * cost_price(50) = 37.5
        self.assertAlmostEqual(txn.loss_value(), 37.5, places=2)
        # Definitely NOT using item.cost_price (9999) in any way
        self.assertNotAlmostEqual(txn.loss_value(), abs(float(txn.qty)) * 9999.0, places=2)

    def test_kitchen_batch_discard_after_prior_sales_correctly_computes_unrecovered_value(self):
        """Edge case caught while writing the fix: discard()'s Wastage row
        has sale_amount=0 (not None) — `is not None` would wrongly take the
        proportional-sale branch (0 * cost_total / revenue_collected = 0)
        instead of falling through to the correct item.cost_price(==
        cost_total) * qty(unrecovered fraction) computation."""
        from core.models import KitchenBatch
        kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        batch_item = Item.objects.create(
            business=self.biz, store=kitchen_store, description='Chipo',
            material_no='LV-BATCH-01', cost_price=Decimal('1000'),
        )
        batch = KitchenBatch.objects.create(
            business=self.biz, store=kitchen_store, item=batch_item,
            cost_total=Decimal('1000'), status='OPEN',
        )
        batch.record_sale(Decimal('600'))  # 600 of 1000 recovered — revenue_collected > 0
        txn = batch.discard('End of day')
        self.assertIsNotNone(txn)
        self.assertEqual(txn.sale_amount, Decimal('0'))
        # unrecovered = 1000 - 600 = 400
        self.assertAlmostEqual(txn.loss_value(), 400.0, places=2)

    def test_kitchen_batch_real_sale_still_proportional_unchanged(self):
        from core.models import KitchenBatch
        kitchen_store = Store.objects.create(business=self.biz, name='Kitchen2', is_kitchen=True)
        batch_item = Item.objects.create(
            business=self.biz, store=kitchen_store, description='Chipo2',
            material_no='LV-BATCH-02', cost_price=Decimal('1000'),
        )
        batch = KitchenBatch.objects.create(
            business=self.biz, store=kitchen_store, item=batch_item,
            cost_total=Decimal('1000'), status='OPEN',
        )
        txn = batch.record_sale(Decimal('500'))  # first sale: 500 of 1000
        # proportional: 500 * 1000 / 500 = 1000 (whole cost attributed to this,
        # the only sale so far) — same formula .cost() always used, unchanged.
        self.assertAlmostEqual(txn.cost(), 1000.0, places=2)

    def test_owner_consumption_uses_loss_value(self):
        item = Item.objects.create(
            business=self.biz, store=self.store, description='Plain Item 2',
            material_no='LV-PLAIN-02', selling_price=Decimal('100'), cost_price=Decimal('40'),
        )
        txn = Transaction.objects.create(
            business=self.biz, item=item, type='OwnerConsumption', qty=Decimal('-1'),
        )
        self.assertEqual(txn.loss_value(), 40.0)

    def test_loss_value_returns_zero_for_issue_type(self):
        """loss_value() is only meaningful for Wastage/OwnerConsumption —
        must never double-count an ordinary sale."""
        item = Item.objects.create(
            business=self.biz, store=self.store, description='Plain Item 3',
            material_no='LV-PLAIN-03', selling_price=Decimal('100'), cost_price=Decimal('40'),
        )
        txn = Transaction.objects.create(
            business=self.biz, item=item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('100'), payment_method='cash',
        )
        self.assertEqual(txn.loss_value(), 0)


class AnalyticsVoidLossIntegrationTest(TestCase):
    """End-to-end: the /analytics/ page itself must show a sane void_loss
    for a voided keg pour, not a multi-million-shilling phantom figure —
    the exact scenario from Roy's live screenshots."""

    def setUp(self):
        _make_keg_setup(self, 'analyticsvoid')

    def test_voided_keg_pour_does_not_inflate_net_profit_loss(self):
        # One real sale so the page has ordinary revenue to compare against.
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-500'), sale_amount=Decimal('50'),
            payment_method='cash', keg_barrel=self.barrel,
        )
        # One VOIDED keg pour — the literal bug scenario.
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-500'), sale_amount=Decimal('50'),
            payment_method='void', keg_barrel=self.barrel,
        )
        self.client.force_login(self.owner)
        resp = self.client.get('/analytics/?period=30')
        self.assertEqual(resp.status_code, 200)
        ctx = resp.context
        # Correct: 50 * 12000 / 18000 ≈ 33.33 — nowhere near a million.
        self.assertLess(ctx['void_loss'], 100)
        self.assertGreater(ctx['void_loss'], 0)
        self.assertLess(abs(ctx['net_profit']), 10_000)


class AnalyticsUnitsFloatRoundingTest(TestCase):
    """2026-08-11 live report (Roy, screenshots): "Blue Ice 32.69999999999997
    units" and "Liquor Store 700.2000000000004 units" — ordinary binary-
    float summation noise (classic `0.1+0.1+0.1 == 0.30000000000000004`)
    from adding many small fractional preset amounts, never rounded before
    display in top_products/store_list, unlike every other accumulated-
    units figure already rounded elsewhere on the same page."""

    def setUp(self):
        self.biz = Business.objects.create(name='Float Rounding Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='floatround_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Blue Ice',
            material_no='FR-01', selling_price=Decimal('80'), cost_price=Decimal('20'),
        )

    def test_top_products_units_never_show_float_noise(self):
        today = timezone.localdate()
        # Three quarter-bottle sales — 0.1 + 0.1 + 0.1 in raw Python floats
        # is 0.30000000000000004, not 0.3.
        for _ in range(3):
            Transaction.objects.create(
                business=self.biz, item=self.item, type='Issue',
                qty=Decimal('-0.1'), sale_amount=Decimal('20'),
                payment_method='cash', date=today,
            )
        self.client.force_login(self.owner)
        resp = self.client.get('/analytics/?period=30')
        self.assertEqual(resp.status_code, 200)
        top = resp.context['top_products']
        self.assertEqual(len(top), 1)
        units = top[0]['units']
        self.assertEqual(units, round(units, 2), 'units must already be exactly 2dp-rounded')
        self.assertEqual(units, 0.3)

    def test_store_list_units_never_show_float_noise(self):
        today = timezone.localdate()
        for _ in range(3):
            Transaction.objects.create(
                business=self.biz, item=self.item, type='Issue',
                qty=Decimal('-0.1'), sale_amount=Decimal('20'),
                payment_method='cash', date=today,
            )
        self.client.force_login(self.owner)
        resp = self.client.get('/analytics/?period=30')
        store_list = resp.context['store_list']
        self.assertEqual(len(store_list), 1)
        units = store_list[0]['units']
        self.assertEqual(units, round(units, 2))
        self.assertEqual(units, 0.3)


class AnalyticsTileBreakdownTest(TestCase):
    """2026-08-11 live request (Roy): tap-to-expand breakdowns for Revenue,
    Gross Profit, Net Profit, Total Expenses, Owner Drawings, and Hasara/
    Losses tiles, so any figure can be checked against the real line items
    behind it instead of taken on faith — the concrete tool for "how do we
    figure out whether revenue is really exaggerated or not"."""

    def setUp(self):
        self.biz = Business.objects.create(name='Breakdown Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='breakdown_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Breakdown Item',
            material_no='BD-01', selling_price=Decimal('100'), cost_price=Decimal('40'),
        )
        self.client.force_login(self.owner)

    def test_revenue_daily_breakdown_matches_real_sales(self):
        today = timezone.localdate()
        yesterday = today - timedelta(days=1)
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('100'), payment_method='cash', date=today,
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('50'), payment_method='cash', date=yesterday,
        )
        resp = self.client.get('/analytics/?period=30')
        breakdown = {str(d['date']): d['revenue'] for d in resp.context['revenue_daily_breakdown']}
        self.assertEqual(breakdown[str(today)], 100.0)
        self.assertEqual(breakdown[str(yesterday)], 50.0)

    def test_prev_period_revenue_shown_for_comparison(self):
        today = timezone.localdate()
        long_ago = today - timedelta(days=35)
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('100'), payment_method='cash', date=today,
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('25'), payment_method='cash', date=long_ago,
        )
        resp = self.client.get('/analytics/?period=30')
        self.assertEqual(resp.context['cur_revenue'], 100.0)
        self.assertEqual(resp.context['prev_revenue'], 25.0)

    def test_owner_drawing_items_lists_real_line_items(self):
        today = timezone.localdate()
        Transaction.objects.create(
            business=self.biz, item=self.item, type='OwnerConsumption',
            qty=Decimal('-2'), date=today,
        )
        resp = self.client.get('/analytics/?period=30')
        items = resp.context['owner_drawing_items']
        self.assertEqual(len(items), 1)
        self.assertEqual(items[0]['name'], 'Breakdown Item')
        self.assertEqual(items[0]['value'], 80.0)  # 2 * 40

    def test_loss_items_lists_wastage_and_void_separately(self):
        today = timezone.localdate()
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Wastage',
            qty=Decimal('-1'), date=today, recipient='Broken',
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('100'), payment_method='void', date=today,
        )
        resp = self.client.get('/analytics/?period=30')
        items = resp.context['loss_items']
        kinds = sorted(it['kind'] for it in items)
        self.assertEqual(kinds, ['Void', 'Wastage'])
        wastage_row = next(it for it in items if it['kind'] == 'Wastage')
        self.assertEqual(wastage_row['reason'], 'Broken')
        self.assertEqual(wastage_row['value'], 40.0)

    def test_expense_items_lists_real_business_expenses(self):
        today = timezone.localdate()
        BusinessExpense.objects.create(
            business=self.biz, category='rent', description='Shop rent',
            amount=Decimal('5000'), date=today,
        )
        resp = self.client.get('/analytics/?period=30')
        items = resp.context['expense_items']
        self.assertEqual(len(items), 1)
        self.assertEqual(items[0]['description'], 'Shop rent')
        self.assertEqual(items[0]['amount'], Decimal('5000'))

    def test_breakdown_panels_render_in_page(self):
        today = timezone.localdate()
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('100'), payment_method='cash', date=today,
        )
        resp = self.client.get('/analytics/?period=30')
        self.assertContains(resp, 'breakdown-panel')
        self.assertContains(resp, 'Tap for daily breakdown')


