class RevertTabFromDebtTest(TestCase):
    """2026-07-30 urgent live request: "a way of reverting tabs sent to
    debt back to the tab drawers they came from in case of a mistake, more
    so on the owner's and manager's side... across all counters."
    convert_tab_to_debt only ever changes recipient (blank -> customer
    name) on still-unpaid entries plus the tab's own status/settled_at —
    payment_method was already 'credit' on every ordinary open-tab charge
    from the moment it was added. Reverting is the precise inverse."""

    def setUp(self):
        self.biz = Business.objects.create(name='Revert Debt Biz', has_kitchen=True)
        self.bar_store = Store.objects.create(business=self.biz, name='Bar')
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='rd_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.manager = User.objects.create_user(username='rd_manager', password='x')
        UserProfile.objects.create(user=self.manager, business=self.biz, role='manager')
        self.staff = User.objects.create_user(username='rd_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        self.item = Item.objects.create(
            business=self.biz, store=self.bar_store, description='Revert Debt Item',
            material_no='RD-01', selling_price=Decimal('480'), cost_price=Decimal('200'),
        )
        self.kitchen_item = Item.objects.create(
            business=self.biz, store=self.kitchen_store, description='Chips',
            material_no='RD-02', selling_price=Decimal('150'), cost_price=Decimal('60'),
        )

    def _make_tab(self, name, amount, item=None, source='bar'):
        item = item or self.item
        store = self.kitchen_store if item is self.kitchen_item else self.bar_store
        tab = BarTab.objects.create(
            business=self.biz, customer_name=name, status='OPEN', source=source, store=store,
        )
        txn = Transaction.objects.create(
            business=self.biz, item=item, type='Issue',
            qty=Decimal('-1'), sale_amount=amount, payment_method='credit',
        )
        entry = BarTabEntry.objects.create(
            tab=tab, transaction=txn, description=item.description, amount=amount, is_paid=False,
        )
        return tab, entry

    def test_owner_reverts_fully_converted_tab(self):
        tab, entry = self._make_tab('Roy', Decimal('480'))
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': 'Roy'})
        tab.refresh_from_db()
        entry.refresh_from_db()
        self.assertEqual(tab.status, 'SETTLED')
        self.assertEqual(entry.transaction.recipient, 'Roy')

        resp = self.client.post(f'/bar/tabs/{tab.id}/revert-debt/')
        data = resp.json()
        self.assertTrue(data['ok'], data)
        tab.refresh_from_db()
        entry.refresh_from_db()
        self.assertEqual(tab.status, 'OPEN')
        self.assertIsNone(tab.settled_at)
        self.assertEqual(entry.transaction.recipient, '')
        self.assertFalse(entry.is_paid)
        self.assertEqual(entry.transaction.payment_method, 'credit')  # untouched — correct baseline

    def test_reverted_tab_no_longer_in_debt_tracker(self):
        from core.debt_views import _get_customer_debt_data
        tab, _entry = self._make_tab('Roy', Decimal('480'))
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': 'Roy'})
        customer = Customer.objects.get(business=self.biz, name='Roy')
        before = _get_customer_debt_data(customer, self.biz)
        self.assertEqual(before['outstanding'], 480.0)

        self.client.post(f'/bar/tabs/{tab.id}/revert-debt/')
        after = _get_customer_debt_data(customer, self.biz)
        self.assertEqual(after['outstanding'], 0.0)

    def test_partial_settle_then_convert_then_revert_only_touches_unpaid_portion(self):
        """Roy's bug-2 scenario, exercised end to end: 480 bill, 200 paid
        via mpesa (a real settle_tab call, splitting the entry), then the
        remaining 280 converted to debt, then reverted — the already-paid
        200 must be untouched throughout."""
        tab, entry = self._make_tab('Roy', Decimal('480'))
        self.client.force_login(self.owner)
        settle_resp = self.client.post(f'/bar/tabs/{tab.id}/settle/', {
            'entry_ids': [entry.id], 'payment_method': 'mpesa', 'amount': '200',
        })
        self.assertTrue(settle_resp.json()['ok'], settle_resp.json())
        self.assertEqual(tab.unpaid_total(), Decimal('280'))

        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': 'Roy'})
        tab.refresh_from_db()
        self.assertEqual(tab.status, 'SETTLED')
        paid_entry = tab.entries.filter(is_paid=True).first()
        self.assertEqual(paid_entry.amount, Decimal('200'))
        self.assertEqual(paid_entry.payment_method, 'mpesa')

        revert_resp = self.client.post(f'/bar/tabs/{tab.id}/revert-debt/')
        self.assertTrue(revert_resp.json()['ok'], revert_resp.json())
        tab.refresh_from_db()
        paid_entry.refresh_from_db()
        self.assertEqual(tab.status, 'OPEN')
        self.assertEqual(tab.unpaid_total(), Decimal('280'))
        self.assertTrue(paid_entry.is_paid)
        self.assertEqual(paid_entry.amount, Decimal('200'))
        self.assertEqual(paid_entry.payment_method, 'mpesa')

    def test_manager_can_revert(self):
        tab, _entry = self._make_tab('Roy', Decimal('480'))
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': 'Roy'})
        self.client.force_login(self.manager)
        resp = self.client.post(f'/bar/tabs/{tab.id}/revert-debt/')
        self.assertTrue(resp.json()['ok'])

    def test_staff_cannot_revert(self):
        tab, _entry = self._make_tab('Roy', Decimal('480'))
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': 'Roy'})
        self.client.force_login(self.staff)
        resp = self.client.post(f'/bar/tabs/{tab.id}/revert-debt/')
        self.assertEqual(resp.status_code, 403)
        tab.refresh_from_db()
        self.assertEqual(tab.status, 'SETTLED')

    def test_blocked_once_customer_has_already_paid_against_it(self):
        tab, _entry = self._make_tab('Roy', Decimal('480'))
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': 'Roy'})
        customer = Customer.objects.get(business=self.biz, name='Roy')
        CustomerDebtPayment.objects.create(
            business=self.biz, customer=customer, amount_paid=Decimal('100'),
        )
        resp = self.client.post(f'/bar/tabs/{tab.id}/revert-debt/')
        self.assertEqual(resp.status_code, 409)
        tab.refresh_from_db()
        self.assertEqual(tab.status, 'SETTLED')

    def test_fully_paid_tab_has_nothing_to_revert(self):
        tab, entry = self._make_tab('Roy', Decimal('480'))
        entry.is_paid = True
        entry.payment_method = 'cash'
        entry.save()
        tab.status = 'SETTLED'
        tab.settled_at = timezone.now()
        tab.save()
        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/tabs/{tab.id}/revert-debt/')
        self.assertEqual(resp.status_code, 400)

    def test_debt_converted_tabs_api_lists_it_station_scoped(self):
        bar_tab, _e1 = self._make_tab('Roy', Decimal('480'), source='bar')
        kitchen_tab, _e2 = self._make_tab('Kim', Decimal('150'), item=self.kitchen_item, source='kitchen')
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{bar_tab.id}/debt/', {'customer_name': 'Roy'})
        self.client.post(f'/bar/tabs/{kitchen_tab.id}/debt/', {'customer_name': 'Kim'})

        resp = self.client.get('/bar/tabs/debt-converted/?station=bar')
        ids = [t['id'] for t in resp.json()['tabs']]
        self.assertIn(bar_tab.id, ids)
        self.assertNotIn(kitchen_tab.id, ids)

        resp = self.client.get('/bar/tabs/debt-converted/?station=kitchen')
        ids = [t['id'] for t in resp.json()['tabs']]
        self.assertIn(kitchen_tab.id, ids)
        self.assertNotIn(bar_tab.id, ids)

    def test_revert_does_not_touch_stock_or_qty(self):
        """Money-position-only correction — the item was genuinely served
        and stock genuinely left the shelf when it was added to the tab,
        completely independent of debt conversion or its reversal."""
        tab, entry = self._make_tab('Roy', Decimal('480'))
        original_qty = entry.transaction.qty
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': 'Roy'})
        self.client.post(f'/bar/tabs/{tab.id}/revert-debt/')
        entry.refresh_from_db()
        self.assertEqual(entry.transaction.qty, original_qty)


class SettleTabRedirectsToDebtPaymentTest(TestCase):
    """2026-08-10 live report (Roy): "when a tab is still in the tabs
    drawer... and the customer had a debt when the auto conversion is
    happening... when the tab is paid and cleared from the tabs drawer, the
    debt tracker still shows it as debt and unpaid one as a matter of
    fact." Root cause: settle_tab()'s `if tab.status != 'OPEN':` branch
    unconditionally returned {ok:True, already_settled:True} the moment a
    tab was no longer OPEN — including a tab that was SETTLED via debt
    conversion (Geuza Deni / shift-close auto-convert) and still had a full
    unpaid balance. A staffer tapping "Lipa Yote" on such a tab (e.g. a
    stale client render, or simply not realizing conversion already
    happened) got a success-shaped response with ZERO record of the real
    cash/mpesa the customer just handed over — the tab vanished from the
    drawer via the caller's own loadTabs() refresh, looking exactly like a
    normal successful settle, while the debt tracker's own figure never
    moved. Fixed by redirecting such a payment into a REAL debt payment via
    the same canonical _do_settle_debt_payment() the debt tracker page and
    the M-Pesa debt-payment callback both already use."""

    def setUp(self):
        self.biz = Business.objects.create(name='Settle Redirect Biz', has_kitchen=True)
        self.bar_store = Store.objects.create(business=self.biz, name='Bar')
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='sr_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.kitchen_staff = User.objects.create_user(username='sr_kstaff', password='x')
        UserProfile.objects.create(user=self.kitchen_staff, business=self.biz, role='kitchen')
        self.item = Item.objects.create(
            business=self.biz, store=self.bar_store, description='Settle Redirect Item',
            material_no='SR-01', selling_price=Decimal('480'), cost_price=Decimal('200'),
        )

    def _make_tab(self, name, amount, source='bar'):
        tab = BarTab.objects.create(
            business=self.biz, customer_name=name, status='OPEN', source=source, store=self.bar_store,
        )
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=amount, payment_method='credit',
        )
        entry = BarTabEntry.objects.create(
            tab=tab, transaction=txn, description=self.item.description, amount=amount, is_paid=False,
        )
        return tab, entry

    def _convert(self, tab, name='Roy'):
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': name})
        tab.refresh_from_db()
        self.assertEqual(tab.status, 'SETTLED')

    def test_settle_on_debt_converted_tab_records_real_debt_payment(self):
        from core.debt_views import _get_customer_debt_data
        tab, entry = self._make_tab('Roy', Decimal('480'))
        self._convert(tab)
        customer = Customer.objects.get(business=self.biz, name='Roy')
        self.assertEqual(_get_customer_debt_data(customer, self.biz)['outstanding'], 480.0)

        resp = self.client.post(f'/bar/tabs/{tab.id}/settle/', {'payment_method': 'cash'})
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.assertTrue(data.get('redirected_to_debt'))
        self.assertIn('receipt_url', data)

        self.assertEqual(CustomerDebtPayment.objects.filter(customer=customer).count(), 1)
        payment = CustomerDebtPayment.objects.get(customer=customer)
        self.assertEqual(payment.amount_paid, Decimal('480'))
        self.assertEqual(payment.payment_method, 'cash')
        self.assertEqual(_get_customer_debt_data(customer, self.biz)['outstanding'], 0.0)

        # _do_settle_debt_payment's own FIFO reconciliation should flip the
        # underlying BarTabEntry to paid once fully covered — same mechanism
        # a normal debt-tracker-page payment already relies on.
        entry.refresh_from_db()
        self.assertTrue(entry.is_paid)

    def test_settle_on_debt_converted_tab_honors_partial_amount(self):
        from core.debt_views import _get_customer_debt_data
        tab, _entry = self._make_tab('Roy', Decimal('480'))
        self._convert(tab)
        customer = Customer.objects.get(business=self.biz, name='Roy')

        resp = self.client.post(f'/bar/tabs/{tab.id}/settle/', {'payment_method': 'mpesa', 'amount': '200'})
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.assertTrue(data.get('redirected_to_debt'))

        payment = CustomerDebtPayment.objects.get(customer=customer)
        self.assertEqual(payment.amount_paid, Decimal('200'))
        self.assertEqual(payment.payment_method, 'mpesa')
        self.assertEqual(_get_customer_debt_data(customer, self.biz)['outstanding'], 280.0)

    def test_settle_on_genuinely_fully_paid_tab_stays_idempotent_noop(self):
        """Regression lock: the original no-op branch must keep working for
        a tab that's SETTLED with NOTHING unpaid left (no customer, or a
        genuine fully-paid-off tab) — no debt payment should ever be
        fabricated for a tab that never carried real debt."""
        tab, entry = self._make_tab('Roy', Decimal('480'))
        entry.is_paid = True
        entry.payment_method = 'cash'
        entry.save()
        tab.status = 'SETTLED'
        tab.settled_at = timezone.now()
        tab.save()
        self.client.force_login(self.owner)

        resp = self.client.post(f'/bar/tabs/{tab.id}/settle/', {'payment_method': 'cash'})
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.assertTrue(data.get('already_settled'))
        self.assertFalse(data.get('redirected_to_debt'))
        self.assertEqual(CustomerDebtPayment.objects.count(), 0)

    def test_settle_on_void_tab_stays_idempotent_noop(self):
        tab, entry = self._make_tab('Roy', Decimal('480'))
        entry.is_paid = True
        entry.payment_method = 'void'
        entry.transaction.payment_method = 'void'
        entry.transaction.save()
        entry.save()
        tab.status = 'VOID'
        tab.settled_at = timezone.now()
        tab.save()
        self.client.force_login(self.owner)

        resp = self.client.post(f'/bar/tabs/{tab.id}/settle/', {'payment_method': 'cash'})
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.assertTrue(data.get('already_settled'))
        self.assertEqual(CustomerDebtPayment.objects.count(), 0)

    def test_settle_redirect_respects_station_scoping(self):
        """A kitchen-only staffer must not be able to redirect a payment
        into a BAR customer's debt via this endpoint, mirroring the
        pre-existing station gate on every other tab-write endpoint."""
        tab, _entry = self._make_tab('Roy', Decimal('480'), source='bar')
        self._convert(tab)
        self.client.force_login(self.kitchen_staff)

        resp = self.client.post(f'/bar/tabs/{tab.id}/settle/', {'payment_method': 'cash'})
        self.assertEqual(resp.status_code, 403)
        self.assertEqual(CustomerDebtPayment.objects.count(), 0)

    def test_settle_redirect_rejects_invalid_amount(self):
        tab, _entry = self._make_tab('Roy', Decimal('480'))
        self._convert(tab)

        resp = self.client.post(f'/bar/tabs/{tab.id}/settle/', {'payment_method': 'cash', 'amount': '0'})
        self.assertEqual(resp.status_code, 400)
        self.assertEqual(CustomerDebtPayment.objects.count(), 0)

        resp = self.client.post(f'/bar/tabs/{tab.id}/settle/', {'payment_method': 'cash', 'amount': 'abc'})
        self.assertEqual(resp.status_code, 400)
        self.assertEqual(CustomerDebtPayment.objects.count(), 0)

    def test_settle_redirect_does_not_touch_stock_or_qty(self):
        """Money-position-only correction, same guarantee as
        revert_tab_from_debt — the item already left the shelf when it was
        first sold on the tab, completely independent of debt conversion
        or how that debt later gets paid off."""
        tab, entry = self._make_tab('Roy', Decimal('480'))
        original_qty = entry.transaction.qty
        self._convert(tab)
        self.client.post(f'/bar/tabs/{tab.id}/settle/', {'payment_method': 'cash'})
        entry.refresh_from_db()
        self.assertEqual(entry.transaction.qty, original_qty)


class DebtConvertedTabsPanelPaymentExclusionTest(TestCase):
    """2026-07-31 live report (Roy): "when the debt payment is recorded,
    the order goes back to the tabs drawer it came from... showing that
    payment was not recorded, or as if it was not just from the debt
    tracker." Root cause: BarTab.unpaid_total() reads only
    BarTabEntry.is_paid, a per-LINE-ITEM flag that only flips once a
    payment has cumulatively covered a line's FULL original amount (see
    _get_customer_debt_data's FIFO walk in core/debt_views.py). A real
    debt-tracker payment (partial OR — depending on timing — even full)
    reduces the customer's TRUE aggregate outstanding balance immediately,
    but the "↩️ Marejesho ya Deni" (revert-from-debt) panel kept showing
    the tab with its stale, un-reduced unpaid_total() regardless, because
    its query (_debt_converted_tabs_qs) only checked for the EXISTENCE of
    an unpaid entry, never whether a payment had actually landed against
    it. Fixed by excluding any tab with a CustomerDebtPayment recorded
    since settled_at — the same condition revert_tab_from_debt itself
    already uses to refuse a revert, so panel visibility and revert
    possibility can never drift apart again."""

    def setUp(self):
        self.biz = Business.objects.create(name='Debt Panel Exclusion Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='dpe_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Debt Panel Item',
            material_no='DPE-01', selling_price=Decimal('500'), cost_price=Decimal('200'),
        )
        self.tab = BarTab.objects.create(
            business=self.biz, customer_name='Roy', status='OPEN', source='bar', store=self.store,
        )
        self.txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('500'), payment_method='credit',
        )
        self.entry = BarTabEntry.objects.create(
            tab=self.tab, transaction=self.txn, description=self.item.description,
            amount=Decimal('500'), is_paid=False,
        )
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{self.tab.id}/debt/', {'customer_name': 'Roy'})
        self.tab.refresh_from_db()
        self.assertEqual(self.tab.status, 'SETTLED')

    def test_panel_shows_freshly_converted_tab(self):
        resp = self.client.get('/bar/tabs/debt-converted/?station=bar')
        ids = [t['id'] for t in resp.json()['tabs']]
        self.assertIn(self.tab.id, ids)

    def test_partial_debt_payment_drops_tab_from_panel_immediately(self):
        """The exact live scenario Roy reported: a genuine partial payment
        recorded via the debt tracker — before this fix, the panel kept
        showing the tab with its FULL original 500, unchanged."""
        customer = Customer.objects.get(business=self.biz, name='Roy')
        resp = self.client.post(f'/debt/{customer.id}/payment/', {
            'amount_paid': '200', 'payment_method': 'cash',
            'idempotency_token': 'dpe-partial-1',
        })
        self.assertEqual(resp.status_code, 302)

        panel_resp = self.client.get('/bar/tabs/debt-converted/?station=bar')
        ids = [t['id'] for t in panel_resp.json()['tabs']]
        self.assertNotIn(
            self.tab.id, ids,
            "tab still shown as revertible/unpaid after a real partial payment",
        )

        # The debt tracker's own aggregate is correctly reduced — proves
        # the payment really was recorded, it just wasn't reflected in the
        # per-line is_paid flag this panel used to rely on.
        from core.debt_views import _get_customer_debt_data
        data = _get_customer_debt_data(customer, self.biz)
        self.assertEqual(data['outstanding'], 300.0)

    def test_full_debt_payment_drops_tab_from_panel(self):
        customer = Customer.objects.get(business=self.biz, name='Roy')
        resp = self.client.post(f'/debt/{customer.id}/payment/', {
            'amount_paid': '500', 'payment_method': 'mpesa',
            'idempotency_token': 'dpe-full-1',
        })
        self.assertEqual(resp.status_code, 302)

        panel_resp = self.client.get('/bar/tabs/debt-converted/?station=bar')
        ids = [t['id'] for t in panel_resp.json()['tabs']]
        self.assertNotIn(self.tab.id, ids)

        self.entry.refresh_from_db()
        self.assertTrue(self.entry.is_paid)

    def test_unpaid_tab_still_correctly_blocks_revert_after_exclusion_fix(self):
        """Sanity check the two mechanisms stay in sync: a tab with no
        payment yet is still both listed AND revertible."""
        panel_resp = self.client.get('/bar/tabs/debt-converted/?station=bar')
        self.assertIn(self.tab.id, [t['id'] for t in panel_resp.json()['tabs']])
        revert_resp = self.client.post(f'/bar/tabs/{self.tab.id}/revert-debt/')
        self.assertTrue(revert_resp.json()['ok'])


class TabToDebtConversionCreditRiskNotificationTest(TestCase):
    """New: a tab-to-debt conversion that adds MORE debt for an already
    credit-risky customer (revoked/permanent defaulter/etc.) now fires a
    non-blocking heads-up Notification to owners/managers — previously this
    was completely invisible, at all three conversion sites (single tab,
    bulk, and shift-close auto-convert)."""

    def setUp(self):
        self.biz = Business.objects.create(
            name='Convert Debt Risk Biz', credit_policy_enabled=True, defaulter_permanent=True,
        )
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='convrisk_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Convert Risk Item',
            material_no='CONVRISK-01', selling_price=Decimal('100'),
        )
        self.risky = Customer.objects.create(
            business=self.biz, name='Risky Patron', credit_approved=True, is_defaulter=True,
        )
        self.client.force_login(self.owner)

    def _make_tab(self, customer_name):
        tab = BarTab.objects.create(business=self.biz, customer_name=customer_name, status='OPEN')
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='tab',
        )
        BarTabEntry.objects.create(tab=tab, transaction=txn, description='Convert Risk Item', amount=Decimal('100'))
        return tab

    def test_single_tab_conversion_notifies_owner_for_risky_customer(self):
        tab = self._make_tab('Risky Patron')
        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': 'Risky Patron'})
        self.assertTrue(
            Notification.objects.filter(user=self.owner, title__icontains='Hatari ya mkopo').exists()
        )

    def test_bulk_conversion_notifies_owner_for_risky_customer(self):
        import json
        tab = self._make_tab('Risky Patron')
        self.client.post('/bar/tabs/bulk-convert-to-debt/', {'tab_ids': json.dumps([tab.id])})
        self.assertTrue(
            Notification.objects.filter(user=self.owner, title__icontains='Hatari ya mkopo').exists()
        )

    def test_shift_close_auto_convert_notifies_owner_for_risky_customer(self):
        from core.shift_views import _convert_open_tabs_to_debt_for_shift
        tab = self._make_tab('Risky Patron')
        shift = Shift.objects.create(
            business=self.biz, store=self.store, staff=self.owner,
            status='OPEN', opening_float=Decimal('0'),
        )
        _convert_open_tabs_to_debt_for_shift(shift, self.biz, True)
        self.assertTrue(
            Notification.objects.filter(user=self.owner, title__icontains='Hatari ya mkopo').exists()
        )

    def test_no_notification_for_clean_customer(self):
        clean = Customer.objects.create(business=self.biz, name='Clean Patron', credit_approved=True)
        tab = self._make_tab('Clean Patron')
        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': 'Clean Patron'})
        self.assertFalse(
            Notification.objects.filter(user=self.owner, title__icontains='Hatari ya mkopo').exists()
        )


class ApproveWriteOffSetsDefaulterTest(TestCase):
    """approve_write_off (an unrecoverable, uncollectable credit loss — the
    business eats it) never set Customer.is_defaulter=True, unlike the
    equally-final void_tab path. Both mean the same thing for the customer's
    future credit standing: this debt was never repaid."""

    def setUp(self):
        self.biz = Business.objects.create(name='WO Defaulter Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='wodef_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='WO Defaulter Item',
            material_no='WODEF-01', selling_price=Decimal('100'),
        )
        self.customer = Customer.objects.create(business=self.biz, name='WO Patron', credit_approved=True)
        self.txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), recipient='WO Patron',
            payment_method='credit', sale_amount=Decimal('100'),
        )
        from core.models import WriteOffRequest
        self.wo = WriteOffRequest.objects.create(
            transaction=self.txn, requested_by=self.owner, reason='test',
            customer_name_cache='WO Patron',
        )
        self.client.force_login(self.owner)

    def test_approval_marks_customer_as_defaulter(self):
        self.client.post(f'/debt/write-off/{self.wo.id}/approve/')
        self.customer.refresh_from_db()
        self.assertTrue(self.customer.is_defaulter)


class WriteOffApprovalExplainsItselfTest(TestCase):
    """2026-07-24 wording/accountability audit: approve_write_off()'s JSON response
    was missing a `message` key entirely (reject_write_off already had one — the
    owner-facing JS already did `d.message || 'Imeidhinishwa.'` and was silently
    falling back to the generic text on every single approval). Separately,
    _mark_receipt_write_off() used to just hide the matching receipt line with
    zero trace — now it's marked with a written_off_at timestamp so the customer's
    own receipt can explain, not just erase, what happened to that item."""

    def setUp(self):
        from core.models import WriteOffRequest, Receipt
        self.WriteOffRequest = WriteOffRequest

        self.biz = Business.objects.create(name='WO Explains Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='woexpl_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='WO Explains Item',
            material_no='WOEXPL-01', selling_price=Decimal('250'),
        )
        self.txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), recipient='WO Explains Patron',
            payment_method='credit', sale_amount=Decimal('250'),
        )
        self.wo = WriteOffRequest.objects.create(
            transaction=self.txn, requested_by=self.owner, reason='test',
            customer_name_cache='WO Explains Patron',
        )
        self.receipt = Receipt.issue(
            business=self.biz,
            lines=[{'name': 'WO Explains Item', 'subtotal': 250.0, 'qty': 1}],
            payment_method='credit', customer_name='WO Explains Patron',
        )
        self.client.force_login(self.owner)

    def test_approve_response_includes_reasoning_message(self):
        resp = self.client.post(f'/debt/write-off/{self.wo.id}/approve/')
        data = resp.json()
        self.assertTrue(data['ok'])
        self.assertIn('message', data)
        self.assertIn('250', data['message'])
        self.assertIn('WO Explains Item', data['message'])
        self.assertIn('WO Explains Patron', data['message'])

    def test_receipt_write_off_marker_includes_timestamp(self):
        self.client.post(f'/debt/write-off/{self.wo.id}/approve/')
        self.receipt.refresh_from_db()
        wo_list = self.receipt.meta.get('write_offs', [])
        self.assertEqual(len(wo_list), 1)
        self.assertIn('written_off_at', wo_list[0])
        self.assertTrue(wo_list[0]['written_off_at'])


class RecordBreakageExplainsItselfTest(TestCase):
    """2026-07-24 wording/accountability audit: record_breakage() used to return a
    bare {"ok": True} with no reasoning trail and never notified the owner/manager
    at all — a real stock/money loss event visible only to the staffer who
    recorded it. Also fixed: 'Item not found' / 'Invalid quantity' were English-only
    in an otherwise all-Swahili flow."""

    def setUp(self):
        self.biz = Business.objects.create(name='Breakage Wording Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='brkword_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(username='brkword_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        Shift.objects.create(business=self.biz, staff=self.staff, status='OPEN')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Breakage Wording Bottle',
            material_no='BRKWORD-01', unit='Pcs', selling_price=Decimal('100'),
            cost_price=Decimal('60'),
        )

    def test_response_includes_reasoning_message_with_reporter_and_loss(self):
        self.client.force_login(self.staff)
        resp = self.client.post('/stock/bar/breakage/', {
            'item_id': self.item.id, 'qty': '2', 'note': 'Imeanguka',
            'idempotency_token': 'brkword-1',
        })
        data = resp.json()
        self.assertTrue(data['ok'])
        self.assertIn('Breakage Wording Bottle', data['message'])
        self.assertIn('120', data['message'])  # 2 x cost_price 60
        self.assertIn('Imeanguka', data['message'])

    def test_owner_notified_of_breakage(self):
        self.client.force_login(self.staff)
        self.client.post('/stock/bar/breakage/', {
            'item_id': self.item.id, 'qty': '1', 'note': 'test',
            'idempotency_token': 'brkword-2',
        })
        notif = Notification.objects.filter(user=self.owner, title__icontains='Uharibifu').first()
        self.assertIsNotNone(notif, 'Owner must be notified when staff records breakage/wastage')

    def test_missing_item_error_is_in_swahili(self):
        self.client.force_login(self.owner)
        resp = self.client.post('/stock/bar/breakage/', {
            'item_id': 999999, 'qty': '1', 'idempotency_token': 'brkword-3',
        })
        self.assertNotIn('Item not found', resp.json().get('error', ''))


class DebtReasoningWordingTest(TestCase):
    """2026-07-24 wording/accountability audit: clear_defaulter()'s notification
    used to say the customer's old debt was 'forgiven' ('amesamehewa deni la
    zamani') — this action only lifts the defaulter block and re-approves credit;
    it does not touch any outstanding balance. That's a different, explicit
    action (approve_write_off). toggle_credit_approval() was also English-only
    (django-i18n _()) in an otherwise all-Swahili file."""

    def setUp(self):
        self.biz = Business.objects.create(name='Debt Wording Biz')
        self.owner = User.objects.create_user(username='debtword_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.customer = Customer.objects.create(
            business=self.biz, name='Debt Wording Patron', is_defaulter=True, credit_approved=False,
        )
        self.client.force_login(self.owner)

    def test_clear_defaulter_message_does_not_claim_debt_forgiven(self):
        resp = self.client.post(f'/debt/{self.customer.id}/clear-defaulter/', follow=True)
        msgs = [str(m) for m in resp.context['messages']]
        joined = ' '.join(msgs)
        self.assertNotIn('amesamehewa', joined)
        self.assertIn('bado linahitaji kulipwa', joined)

    def test_clear_defaulter_notification_includes_reviewer_and_timestamp(self):
        self.client.post(f'/debt/{self.customer.id}/clear-defaulter/')
        notif = Notification.objects.filter(user=self.owner, title__icontains='Ameruhusiwa').first()
        self.assertIsNotNone(notif)
        self.assertIn('debtword_owner', notif.message)

    def test_toggle_credit_approval_message_is_in_swahili(self):
        resp = self.client.post(f'/debt/{self.customer.id}/toggle-credit/', follow=True)
        msgs = [str(m) for m in resp.context['messages']]
        joined = ' '.join(msgs)
        self.assertIn('Mkopo', joined)
        self.assertIn('Debt Wording Patron', joined)
        self.assertNotIn('Credit', joined)


# ══════════════════════════════════════════════════════════════════════════════
# Debt Tracker Module Audit — Theme 3 (access-control scoping), 2026-07-21
# ══════════════════════════════════════════════════════════════════════════════

class RequestWriteOffStationScopingTest(TestCase):
    """request_write_off had no station gate at all — a bar-only staffer could
    pass any txn_id and both see (item name, amount, customer) AND act on a
    kitchen credit transaction, and vice versa. Owner/manager always see both."""

    def setUp(self):
        self.biz = Business.objects.create(name='WO Station Scope Biz', has_kitchen=True)
        self.bar_store = Store.objects.create(business=self.biz, name='Bar', is_kitchen=False)
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)

        self.owner = User.objects.create_user(username='wostation_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')

        self.bar_staff = User.objects.create_user(username='wostation_barstaff', password='x')
        UserProfile.objects.create(
            user=self.bar_staff, business=self.biz, role='staff',
            can_access_bar=True, can_access_kitchen=False,
        )
        self.kitchen_staff = User.objects.create_user(username='wostation_kitchenstaff', password='x')
        UserProfile.objects.create(
            user=self.kitchen_staff, business=self.biz, role='kitchen',
            can_access_bar=False, can_access_kitchen=False,
        )

        self.bar_item = Item.objects.create(
            business=self.biz, store=self.bar_store, description='WO Station Bar Item',
            material_no='WOSTATIONBAR-01', selling_price=Decimal('100'),
        )
        self.kitchen_item = Item.objects.create(
            business=self.biz, store=self.kitchen_store, description='WO Station Kitchen Item',
            material_no='WOSTATIONKITCHEN-01', selling_price=Decimal('100'),
        )
        self.bar_txn = Transaction.objects.create(
            business=self.biz, item=self.bar_item, type='Issue',
            qty=Decimal('-1'), recipient='Bar Patron',
            payment_method='credit', sale_amount=Decimal('100'),
        )
        self.kitchen_txn = Transaction.objects.create(
            business=self.biz, item=self.kitchen_item, type='Issue',
            qty=Decimal('-1'), recipient='Kitchen Patron',
            payment_method='credit', sale_amount=Decimal('100'),
        )

    def test_bar_only_staff_cannot_write_off_kitchen_transaction(self):
        self.client.force_login(self.bar_staff)
        resp = self.client.post(
            f'/debt/write-off/request/{self.kitchen_txn.id}/', {'reason': 'test'},
        )
        self.assertEqual(resp.status_code, 403)

    def test_kitchen_only_staff_cannot_write_off_bar_transaction(self):
        self.client.force_login(self.kitchen_staff)
        resp = self.client.post(
            f'/debt/write-off/request/{self.bar_txn.id}/', {'reason': 'test'},
        )
        self.assertEqual(resp.status_code, 403)

    def test_bar_only_staff_can_write_off_bar_transaction(self):
        self.client.force_login(self.bar_staff)
        resp = self.client.post(
            f'/debt/write-off/request/{self.bar_txn.id}/', {'reason': 'test'},
        )
        self.assertEqual(resp.json().get('ok'), True)

    def test_owner_can_write_off_either_station(self):
        self.client.force_login(self.owner)
        resp1 = self.client.post(
            f'/debt/write-off/request/{self.bar_txn.id}/', {'reason': 'test'},
        )
        resp2 = self.client.post(
            f'/debt/write-off/request/{self.kitchen_txn.id}/', {'reason': 'test'},
        )
        self.assertEqual(resp1.json().get('ok'), True)
        self.assertEqual(resp2.json().get('ok'), True)


class DebtEraseMistakeTest(TestCase):
    """2026-07-31 live request: "when an item is out on a running tab or debt
    section, the system should consider it as a stock deduction... and when
    the item is erased the system should append the balances accordingly."
    A genuinely mistaken debt entry (wrong item/customer) is different from
    a real, uncollectable Write-off — 'Ilikuwa Kosa' restores stock the same
    way removing a live tab entry already does, is self-service by default
    (Roy's explicit call), and never flags the customer as a defaulter."""

    def setUp(self):
        self.biz = Business.objects.create(name='Debt Erase Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='derase_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.manager = User.objects.create_user(username='derase_manager', password='x')
        self.manager_profile = UserProfile.objects.create(
            user=self.manager, business=self.biz, role='manager',
        )
        self.staff = User.objects.create_user(username='derase_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Debt Erase Item',
            material_no='DERASE-01', selling_price=Decimal('100'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('20'),
        )

    def _make_credit_txn(self, customer_name='Erase Patron'):
        return Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-2'), recipient=customer_name,
            payment_method='credit', sale_amount=Decimal('200'),
        )

    def _open_shift(self, user):
        return Shift.objects.create(
            business=self.biz, staff=user, status='OPEN',
            started_at=timezone.now() - timedelta(hours=1),
        )

    # ── Self-service default (Business.debt_erase_requires_approval=False) ──

    def test_owner_self_service_erase_executes_immediately_and_restores_stock(self):
        txn = self._make_credit_txn()
        before = self.item.current_balance()
        self.client.force_login(self.owner)
        resp = self.client.post(f'/debt/write-off/request/{txn.id}/', {
            'reason': 'Wrong customer entirely', 'is_mistake': '1',
        })
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.assertTrue(data.get('executed'))
        txn.refresh_from_db()
        self.assertEqual(txn.payment_method, 'void')
        self.assertEqual(txn.qty, Decimal('0'))
        self.assertEqual(self.item.current_balance(), before + 2)

    def test_self_service_erase_never_flags_customer_as_defaulter(self):
        customer = Customer.objects.create(business=self.biz, name='Erase Patron', credit_approved=True)
        txn = self._make_credit_txn(customer_name='Erase Patron')
        self.client.force_login(self.owner)
        self.client.post(f'/debt/write-off/request/{txn.id}/', {
            'reason': 'Data entry mistake', 'is_mistake': '1',
        })
        customer.refresh_from_db()
        self.assertFalse(customer.is_defaulter)

    def test_staff_with_open_shift_can_self_service_erase(self):
        self._open_shift(self.staff)
        txn = self._make_credit_txn()
        self.client.force_login(self.staff)
        resp = self.client.post(f'/debt/write-off/request/{txn.id}/', {
            'reason': 'Mistake', 'is_mistake': '1',
        })
        self.assertTrue(resp.json().get('ok'))
        self.assertTrue(resp.json().get('executed'))

    def test_staff_without_open_shift_cannot_self_service_erase(self):
        txn = self._make_credit_txn()
        self.client.force_login(self.staff)
        resp = self.client.post(f'/debt/write-off/request/{txn.id}/', {
            'reason': 'Mistake', 'is_mistake': '1',
        })
        self.assertEqual(resp.status_code, 403)
        txn.refresh_from_db()
        self.assertEqual(txn.payment_method, 'credit')

    def test_regular_writeoff_request_unaffected_by_default(self):
        """is_mistake omitted/false — behaves exactly as before this feature:
        creates a pending request, does not execute, no shift required."""
        txn = self._make_credit_txn()
        self.client.force_login(self.staff)
        resp = self.client.post(f'/debt/write-off/request/{txn.id}/', {'reason': 'Real debt'})
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.assertNotIn('executed', data)
        txn.refresh_from_db()
        self.assertEqual(txn.payment_method, 'credit')

    # ── Approval-gated opt-in (Business.debt_erase_requires_approval=True) ──

    def test_approval_gated_erase_creates_pending_request_not_executed(self):
        self.biz.debt_erase_requires_approval = True
        self.biz.save(update_fields=['debt_erase_requires_approval'])
        self._open_shift(self.staff)
        txn = self._make_credit_txn()
        self.client.force_login(self.staff)
        resp = self.client.post(f'/debt/write-off/request/{txn.id}/', {
            'reason': 'Mistake', 'is_mistake': '1',
        })
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.assertNotIn('executed', data)
        txn.refresh_from_db()
        self.assertEqual(txn.payment_method, 'credit')

        from core.models import WriteOffRequest
        wo = WriteOffRequest.objects.get(transaction=txn)
        self.assertEqual(wo.status, WriteOffRequest.STATUS_PENDING)
        self.assertEqual(wo.request_type, WriteOffRequest.TYPE_ERASE_MISTAKE)

    def test_manager_without_permission_cannot_approve_erase_mistake(self):
        self.biz.debt_erase_requires_approval = True
        self.biz.save(update_fields=['debt_erase_requires_approval'])
        txn = self._make_credit_txn()
        from core.models import WriteOffRequest
        wo = WriteOffRequest.objects.create(
            transaction=txn, requested_by=self.staff, reason='Mistake',
            customer_name_cache='Erase Patron', request_type=WriteOffRequest.TYPE_ERASE_MISTAKE,
        )
        self.client.force_login(self.manager)
        resp = self.client.post(f'/debt/write-off/{wo.id}/approve/')
        self.assertEqual(resp.status_code, 403)

    def test_manager_with_permission_can_approve_erase_mistake_and_restores_stock(self):
        self.biz.debt_erase_requires_approval = True
        self.biz.save(update_fields=['debt_erase_requires_approval'])
        self.manager_profile.can_approve_debt_erase = True
        self.manager_profile.save(update_fields=['can_approve_debt_erase'])
        txn = self._make_credit_txn()
        before = self.item.current_balance()
        from core.models import WriteOffRequest
        wo = WriteOffRequest.objects.create(
            transaction=txn, requested_by=self.staff, reason='Mistake',
            customer_name_cache='Erase Patron', request_type=WriteOffRequest.TYPE_ERASE_MISTAKE,
        )
        self.client.force_login(self.manager)
        resp = self.client.post(f'/debt/write-off/{wo.id}/approve/')
        self.assertTrue(resp.json().get('ok'), resp.json())
        txn.refresh_from_db()
        self.assertEqual(txn.payment_method, 'void')
        self.assertEqual(txn.qty, Decimal('0'))
        self.assertEqual(self.item.current_balance(), before + 2)

    def test_manager_with_erase_permission_still_cannot_approve_real_writeoff(self):
        """The permission never extends to a real, uncollectable debt —
        that final decision always stays owner-only."""
        self.manager_profile.can_approve_debt_erase = True
        self.manager_profile.save(update_fields=['can_approve_debt_erase'])
        txn = self._make_credit_txn()
        from core.models import WriteOffRequest
        wo = WriteOffRequest.objects.create(
            transaction=txn, requested_by=self.staff, reason='Real debt, uncollectable',
            customer_name_cache='Erase Patron',
        )
        self.client.force_login(self.manager)
        resp = self.client.post(f'/debt/write-off/{wo.id}/approve/')
        self.assertEqual(resp.status_code, 403)

    def test_owner_can_always_approve_either_type(self):
        self.biz.debt_erase_requires_approval = True
        self.biz.save(update_fields=['debt_erase_requires_approval'])
        txn1 = self._make_credit_txn(customer_name='Patron A')
        txn2 = self._make_credit_txn(customer_name='Patron B')
        from core.models import WriteOffRequest
        wo_mistake = WriteOffRequest.objects.create(
            transaction=txn1, requested_by=self.staff, reason='Mistake',
            customer_name_cache='Patron A', request_type=WriteOffRequest.TYPE_ERASE_MISTAKE,
        )
        wo_real = WriteOffRequest.objects.create(
            transaction=txn2, requested_by=self.staff, reason='Real debt',
            customer_name_cache='Patron B',
        )
        self.client.force_login(self.owner)
        resp1 = self.client.post(f'/debt/write-off/{wo_mistake.id}/approve/')
        resp2 = self.client.post(f'/debt/write-off/{wo_real.id}/approve/')
        self.assertTrue(resp1.json().get('ok'), resp1.json())
        self.assertTrue(resp2.json().get('ok'), resp2.json())

    def test_rejecting_erase_mistake_creates_no_haki_deduction(self):
        """Unlike rejecting a real write-off (which penalises the requester
        for asking to forgive real money), being told a flagged 'mistake' is
        actually a real debt is not the same failure — no salary deduction."""
        txn = self._make_credit_txn()
        from core.models import WriteOffRequest
        wo = WriteOffRequest.objects.create(
            transaction=txn, requested_by=self.staff, reason='Mistake',
            customer_name_cache='Erase Patron', request_type=WriteOffRequest.TYPE_ERASE_MISTAKE,
        )
        self.client.force_login(self.owner)
        resp = self.client.post(f'/debt/write-off/{wo.id}/reject/')
        self.assertTrue(resp.json().get('ok'), resp.json())
        from core.models import SalaryDeduction
        self.assertEqual(SalaryDeduction.objects.filter(write_off=wo).count(), 0)
        txn.refresh_from_db()
        self.assertEqual(txn.payment_method, 'credit')

    def test_rejecting_real_writeoff_still_creates_haki_deduction(self):
        """Regression lock: the pre-existing real-write-off rejection penalty
        must be completely unaffected by this feature."""
        txn = self._make_credit_txn()
        from core.models import WriteOffRequest
        wo = WriteOffRequest.objects.create(
            transaction=txn, requested_by=self.staff, reason='Real debt',
            customer_name_cache='Erase Patron',
        )
        self.client.force_login(self.owner)
        resp = self.client.post(f'/debt/write-off/{wo.id}/reject/')
        self.assertTrue(resp.json().get('ok'), resp.json())
        from core.models import SalaryDeduction
        self.assertEqual(SalaryDeduction.objects.filter(write_off=wo).count(), 1)


