# ── Fix: stock-count correction mislabeled as plain Receipt (2026-07-22) ──────
# Roy reported live: he mistyped a stock take (4 instead of 5), corrected it by
# recounting to 5, and the resulting +1 correction showed in Transaction
# History as an unmarked "Receipt" — indistinguishable from a real supplier
# delivery. invoice_no='[ADJ]' was already set on the surplus branch (to
# suppress the "missing cost price" alert) but the UI never used it to show
# anything different, and the shortage branch didn't set it at all.

class AdjustStockBalanceCorrectionTaggingTest(TestCase):
    def setUp(self):
        self.biz = Business.objects.create(name='ADJ Tag Biz')
        self.store = Store.objects.create(business=self.biz, name='Main')
        self.owner = User.objects.create_user(username='adjtag_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='ADJ Tag Item',
            material_no='ADJTAG-01', unit='Pcs', selling_price=Decimal('100'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('4'),
        )
        self.client.force_login(self.owner)

    def test_surplus_correction_tagged_adj(self):
        self.client.post(f'/stock/items/{self.item.id}/adjust/', {'actual_count': '5'})
        txn = Transaction.objects.filter(business=self.biz, item=self.item, type='Receipt', qty=Decimal('1')).first()
        self.assertIsNotNone(txn)
        self.assertEqual(txn.invoice_no, '[ADJ]')

    def test_shortage_correction_now_also_tagged_adj(self):
        self.client.post(f'/stock/items/{self.item.id}/adjust/', {'actual_count': '2'})
        txn = Transaction.objects.filter(business=self.biz, item=self.item, type='Wastage').first()
        self.assertIsNotNone(txn)
        self.assertEqual(txn.invoice_no, '[ADJ]')

    def test_transaction_history_shows_rekebisho_not_receipt(self):
        self.client.post(f'/stock/items/{self.item.id}/adjust/', {'actual_count': '5'})
        resp = self.client.get('/history/')
        self.assertIn(b'Rekebisho', resp.content)


# ── reconcile_kitchen_stores management command (2026-07-22) ─────────────────
# One-time cleanup tool for the duplicate-kitchen-store bug fixed the same
# day (commit 0228411) — Roy needed a way to fix it on live production
# without direct DB access, so this is a safe, dry-run-by-default command
# rather than a direct data fix.

class ReconcileKitchenStoresCommandTest(TestCase):
    def setUp(self):
        self.biz = Business.objects.create(name='Reconcile Cmd Biz')

    def _call(self, *args):
        from io import StringIO
        from django.core.management import call_command
        out = StringIO()
        call_command('reconcile_kitchen_stores', *args, stdout=out)
        return out.getvalue()

    def test_dry_run_does_not_change_anything(self):
        real = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=False)
        Item.objects.create(
            business=self.biz, store=real, description='Cmd Item',
            material_no='RKCMD-01', selling_price=Decimal('50'),
        )
        dup = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)

        output = self._call('--business', 'Reconcile Cmd Biz')

        self.assertIn('Would flag', output)
        self.assertIn('Would DELETE', output)
        real.refresh_from_db()
        self.assertFalse(real.is_kitchen)
        self.assertTrue(Store.objects.filter(id=dup.id).exists())

    def test_apply_flags_real_store_and_deletes_empty_duplicate(self):
        real = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=False)
        item = Item.objects.create(
            business=self.biz, store=real, description='Cmd Item',
            material_no='RKCMD-02', selling_price=Decimal('50'),
        )
        dup = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)

        self._call('--business', 'Reconcile Cmd Biz', '--apply')

        real.refresh_from_db()
        self.assertTrue(real.is_kitchen)
        self.assertFalse(Store.objects.filter(id=dup.id).exists())
        item.refresh_from_db()
        self.assertEqual(item.store_id, real.id)

    def test_apply_skips_ambiguous_case_with_items_on_both(self):
        s1 = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=False)
        Item.objects.create(
            business=self.biz, store=s1, description='Item A',
            material_no='RKCMD-A', selling_price=Decimal('50'),
        )
        s2 = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        Item.objects.create(
            business=self.biz, store=s2, description='Item B',
            material_no='RKCMD-B', selling_price=Decimal('50'),
        )

        output = self._call('--business', 'Reconcile Cmd Biz', '--apply')

        self.assertIn('AMBIGUOUS', output)
        self.assertEqual(Store.objects.filter(business=self.biz).count(), 2)

    def test_apply_handles_both_stores_completely_empty(self):
        """Real-world case reported by Roy for Monsoon Inn: neither store had
        any items at all (the business had just enabled the kitchen module,
        no items added yet). Nothing to lose either way, so the already-
        flagged store is kept and the unflagged duplicate is deleted."""
        unflagged = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=False)
        flagged = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)

        output = self._call('--business', 'Reconcile Cmd Biz', '--apply')

        self.assertIn('Would DELETE', output)
        self.assertFalse(Store.objects.filter(id=unflagged.id).exists())
        flagged.refresh_from_db()
        self.assertTrue(Store.objects.filter(id=flagged.id).exists())
        self.assertTrue(flagged.is_kitchen)

    def test_shift_on_one_store_counts_as_activity_not_just_items(self):
        """A store can have real history (shifts, tabs, barrels) with zero
        Items currently attached — activity must be checked broadly, not
        just via item_count, or a store with real shift history could be
        misjudged 'empty' and deleted."""
        from core.models import Shift
        with_shift = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=False)
        empty = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        staff = User.objects.create_user(username='rkcmd_shift_staff', password='x')
        UserProfile.objects.create(user=staff, business=self.biz, role='staff')
        Shift.objects.create(business=self.biz, store=with_shift, staff=staff, opening_float=Decimal('0'))

        self._call('--business', 'Reconcile Cmd Biz', '--apply')

        with_shift.refresh_from_db()
        self.assertTrue(with_shift.is_kitchen)
        self.assertFalse(Store.objects.filter(id=empty.id).exists())

    def test_other_business_unaffected(self):
        other = Business.objects.create(name='Reconcile Cmd Other Biz')
        Store.objects.create(business=other, name='Kitchen', is_kitchen=False)
        Store.objects.create(business=other, name='Kitchen', is_kitchen=True)

        self._call('--business', 'Reconcile Cmd Biz', '--apply')

        self.assertEqual(Store.objects.filter(business=other).count(), 2)


# ── Raw-material sack tracking (two-level Kitchen Batch cost derivation), 2026-07-22 ──
# Item.raw_material_source (self-FK) + KitchenBatch.open_batch() classmethod let a
# batch item (e.g. Chipo) draw its daily cost from a real, trackable raw-material
# Item (e.g. "Potatoes (Raw)") instead of a typed guess. Also fixes a real,
# pre-existing bug found while designing this: Transaction.cost() had no
# kitchen_batch_id branch, so every sale from a batch reported cost = the WHOLE
# batch's cost_total instead of a proportional share.

class KitchenBatchOpenBatchDrawTest(TestCase):
    """KitchenBatch.open_batch() — draw-from-sack path (model layer)."""

    def setUp(self):
        _make_kitchen_setup(self, biz_suffix='draw')
        self.raw_item = Item.objects.create(
            business=self.biz, store=self.store, description='Potatoes (Raw)',
            unit='Kg', material_no='RAW-DRAW-01', cost_price=Decimal('50'),
            opening_bin_balance=100,
        )
        self.item.raw_material_source = self.raw_item
        self.item.save(update_fields=['raw_material_source'])

    def test_draw_derives_cost_and_decrements_raw_balance(self):
        batch = KitchenBatch.open_batch(
            business=self.biz, store=self.store, item=self.item,
            recorded_by=self.owner_user, draw_qty=Decimal('10'),
        )
        self.assertEqual(batch.cost_total, Decimal('500.00'))
        self.assertEqual(batch.source_item_id, self.raw_item.id)
        self.assertEqual(batch.source_qty_drawn, Decimal('10'))
        self.raw_item.refresh_from_db()
        self.assertEqual(self.raw_item.current_balance(), 90)

    def test_draw_creates_draw_type_transaction_not_issue(self):
        KitchenBatch.open_batch(
            business=self.biz, store=self.store, item=self.item,
            recorded_by=self.owner_user, draw_qty=Decimal('5'),
        )
        txn = Transaction.objects.filter(item=self.raw_item).latest('id')
        self.assertEqual(txn.type, 'Draw')
        self.assertEqual(txn.qty, Decimal('-5'))

    def test_draw_sets_item_cost_price_to_cost_total(self):
        batch = KitchenBatch.open_batch(
            business=self.biz, store=self.store, item=self.item,
            recorded_by=self.owner_user, draw_qty=Decimal('4'),
        )
        self.item.refresh_from_db()
        self.assertEqual(self.item.cost_price, batch.cost_total)

    def test_insufficient_balance_raises_and_creates_nothing(self):
        with self.assertRaises(ValueError):
            KitchenBatch.open_batch(
                business=self.biz, store=self.store, item=self.item,
                recorded_by=self.owner_user, draw_qty=Decimal('999'),
            )
        self.assertEqual(KitchenBatch.objects.filter(item=self.item).count(), 0)
        self.assertEqual(Transaction.objects.filter(item=self.raw_item).count(), 0)
        self.raw_item.refresh_from_db()
        self.assertEqual(self.raw_item.current_balance(), 100)

    def test_zero_draw_qty_rejected(self):
        with self.assertRaises(ValueError):
            KitchenBatch.open_batch(
                business=self.biz, store=self.store, item=self.item,
                recorded_by=self.owner_user, draw_qty=Decimal('0'),
            )

    def test_manual_cost_path_unaffected_when_no_raw_source(self):
        """Items without raw_material_source keep the original manual-cost
        flow, completely unchanged — this feature is opt-in only."""
        self.item.raw_material_source = None
        self.item.save(update_fields=['raw_material_source'])
        batch = KitchenBatch.open_batch(
            business=self.biz, store=self.store, item=self.item,
            recorded_by=self.owner_user, cost_total=Decimal('1500'),
        )
        self.assertEqual(batch.cost_total, Decimal('1500'))
        self.assertIsNone(batch.source_item_id)
        self.assertEqual(Transaction.objects.filter(type='Draw').count(), 0)

    def test_sequential_draws_deduct_balance_correctly(self):
        """Mirrors KitchenEnvelopeSaleLockTest's convention — locks in that
        repeated draws (select_for_update) accumulate/deduct correctly rather
        than losing an update, the multi-pot case being explicitly allowed."""
        for _i in range(3):
            KitchenBatch.open_batch(
                business=self.biz, store=self.store, item=self.item,
                recorded_by=self.owner_user, draw_qty=Decimal('10'),
            )
        self.raw_item.refresh_from_db()
        self.assertEqual(self.raw_item.current_balance(), 70)
        self.assertEqual(
            Transaction.objects.filter(item=self.raw_item, type='Draw').count(), 3
        )


class TransactionCostKitchenBatchProportionalTest(TestCase):
    """Transaction.cost() must return a PROPORTIONAL share of the batch's
    cost_total per sale, not the whole cost_total on every sale. Found
    2026-07-22 while designing raw-material sack tracking: item.cost_price is
    deliberately set to the batch's WHOLE cost_total (discard()'s wastage math
    relies on this), but qty on every kitchen batch sale is a constant -1 —
    so falling through to abs(qty) * item.cost_price returned cost_total on
    EVERY sale, a real overcounting bug in Kitchen Performance / overall COGS
    for any batch sold more than once."""

    def setUp(self):
        _make_kitchen_setup(self, biz_suffix='costfix')
        self.batch = KitchenBatch.objects.create(
            business=self.biz, store=self.store, item=self.item,
            cost_total=Decimal('1000'),
        )
        self.item.cost_price = Decimal('1000')
        self.item.save(update_fields=['cost_price'])

    def test_single_sale_cost_equals_full_cost_total(self):
        txn = self.batch.record_sale(Decimal('1000'), preset=self.preset)
        self.assertAlmostEqual(txn.cost(), 1000.0)

    def test_multiple_sales_sum_to_cost_total_not_multiple(self):
        txns = [self.batch.record_sale(amount, preset=self.preset)
                for amount in (Decimal('200'), Decimal('300'), Decimal('500'))]
        total_cost = sum(t.cost() for t in txns)
        self.assertAlmostEqual(total_cost, 1000.0)
        # Without the fix this would be 3 x 1000 = 3000 (the pre-existing bug).
        self.assertNotAlmostEqual(total_cost, 3000.0)

    def test_draw_transaction_cost_is_always_zero(self):
        """A Draw is an internal stock movement, not a sale — its cost is
        recognized once, when the cooked product is later sold (above), not
        here. Otherwise the same KES would be double-counted."""
        raw_item = Item.objects.create(
            business=self.biz, store=self.store, description='Raw Draw Cost Test',
            unit='Kg', material_no='RAWCOST-01', cost_price=Decimal('50'),
            opening_bin_balance=50,
        )
        txn = Transaction.objects.create(
            item=raw_item, business=self.biz, type='Draw', qty=Decimal('-5'),
        )
        self.assertEqual(txn.cost(), 0)


class RawMaterialSackTrackingViewTest(TestCase):
    """/kitchen/receive/ and /kitchen/batch/receive/ mode=kitchen_batch draw
    path (view layer) — both call sites must stay in sync."""

    def setUp(self):
        _make_kitchen_setup(self, biz_suffix='sackview')
        self.raw_item = Item.objects.create(
            business=self.biz, store=self.store, description='Potatoes (Raw)',
            unit='Kg', material_no='RAWVIEW-01', cost_price=Decimal('50'),
            opening_bin_balance=100,
        )
        self.item.raw_material_source = self.raw_item
        self.item.save(update_fields=['raw_material_source'])
        self.client.force_login(self.owner_user)

    def test_kitchen_receive_draw_mode_creates_batch_with_derived_cost(self):
        resp = self.client.post('/kitchen/receive/', {
            'mode': 'kitchen_batch',
            'item_id': self.item.id,
            'draw_qty': '10',
        })
        data = resp.json()
        self.assertTrue(data.get('ok'), data)
        batch = KitchenBatch.objects.get(id=data['batch']['id'])
        self.assertEqual(batch.cost_total, Decimal('500.00'))
        self.raw_item.refresh_from_db()
        self.assertEqual(self.raw_item.current_balance(), 90)

    def test_kitchen_receive_draw_exceeding_balance_errors_with_no_side_effects(self):
        resp = self.client.post('/kitchen/receive/', {
            'mode': 'kitchen_batch',
            'item_id': self.item.id,
            'draw_qty': '500',
        })
        data = resp.json()
        self.assertFalse(data.get('ok'))
        self.assertEqual(KitchenBatch.objects.filter(item=self.item).count(), 0)
        self.raw_item.refresh_from_db()
        self.assertEqual(self.raw_item.current_balance(), 100)

    def test_kitchen_receive_item_without_raw_source_still_uses_manual_cost(self):
        self.item.raw_material_source = None
        self.item.save(update_fields=['raw_material_source'])
        resp = self.client.post('/kitchen/receive/', {
            'mode': 'kitchen_batch',
            'item_id': self.item.id,
            'cost_total': '1500',
        })
        data = resp.json()
        self.assertTrue(data.get('ok'), data)
        batch = KitchenBatch.objects.get(id=data['batch']['id'])
        self.assertEqual(batch.cost_total, Decimal('1500'))
        self.assertIsNone(batch.source_item_id)

    def test_kitchen_batch_receive_duplicate_endpoint_supports_draw_mode(self):
        """kitchen_batch_receive is a second, UI-dead-but-live URL that must
        stay in parity with kitchen_receive's kitchen_batch mode."""
        resp = self.client.post('/kitchen/batch/receive/', {
            'item_id': self.item.id,
            'draw_qty': '8',
        })
        data = resp.json()
        self.assertTrue(data.get('ok'), data)
        batch = KitchenBatch.objects.get(id=data['batch']['id'])
        self.assertEqual(batch.cost_total, Decimal('400.00'))
        self.raw_item.refresh_from_db()
        self.assertEqual(self.raw_item.current_balance(), 92)


class ItemFormRawMaterialSourceTest(TestCase):
    """add_item / edit_item — km_raw_source POST field sets/clears
    Item.raw_material_source."""

    def setUp(self):
        self.biz = Business.objects.create(name='RawSrc Form Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner_user = User.objects.create_user(username='rawsrc_owner', password='x')
        UserProfile.objects.create(user=self.owner_user, business=self.biz, role='owner')
        self.raw_item = Item.objects.create(
            business=self.biz, store=self.store, description='Potatoes (Raw)',
            unit='Kg', material_no='RAWFORM-01', is_kitchen_batch=False,
        )
        self.client.force_login(self.owner_user)

    def test_add_item_sets_raw_material_source(self):
        resp = self.client.post('/stock/add/', {
            'description': 'Chipo Form Test', 'store': self.store.id,
            'is_kitchen_batch': 'on', 'km_raw_source': self.raw_item.id,
        })
        self.assertEqual(resp.status_code, 302)
        item = Item.objects.get(description='Chipo Form Test', business=self.biz)
        self.assertTrue(item.is_kitchen_batch)
        self.assertEqual(item.raw_material_source_id, self.raw_item.id)

    def test_add_item_leaves_raw_material_source_null_when_not_selected(self):
        resp = self.client.post('/stock/add/', {
            'description': 'Mchuzi Form Test', 'store': self.store.id,
            'is_kitchen_batch': 'on',
        })
        self.assertEqual(resp.status_code, 302)
        item = Item.objects.get(description='Mchuzi Form Test', business=self.biz)
        self.assertIsNone(item.raw_material_source_id)

    def test_edit_item_can_clear_raw_material_source(self):
        batch_item = Item.objects.create(
            business=self.biz, store=self.store, description='Chipo Edit Test',
            unit='Batch', material_no='CHIPOEDIT-01', is_kitchen_batch=True,
            raw_material_source=self.raw_item,
        )
        resp = self.client.post(f'/stock/edit/{batch_item.id}/', {
            'description': 'Chipo Edit Test', 'store': self.store.id,
            'is_kitchen_batch': 'on',
            # km_raw_source omitted → should clear the FK
        })
        self.assertEqual(resp.status_code, 302)
        batch_item.refresh_from_db()
        self.assertIsNone(batch_item.raw_material_source_id)

    def test_edit_item_cannot_self_reference(self):
        """A batch item can't be picked as its own raw material source —
        the queryset for the picker already excludes it server-side; this
        locks in that a spoofed self-id POST is also rejected, not just
        hidden from the dropdown."""
        batch_item = Item.objects.create(
            business=self.biz, store=self.store, description='Chipo Self Test',
            unit='Batch', material_no='CHIPOSELF-01', is_kitchen_batch=True,
        )
        resp = self.client.post(f'/stock/edit/{batch_item.id}/', {
            'description': 'Chipo Self Test', 'store': self.store.id,
            'is_kitchen_batch': 'on', 'km_raw_source': batch_item.id,
        })
        self.assertEqual(resp.status_code, 302)
        batch_item.refresh_from_db()
        self.assertIsNone(batch_item.raw_material_source_id)


# ── Split bill across two customers' tabs (2026-07-23 live request) ──────────
# "Roy pays 400 of his 600 Smirnoff, his friend Bosco's tab picks up the
# remaining 200." See BarTabEntry.split_and_transfer_locked() / TabTransferRequest
# in core/models.py, and core/keg_views.py's split_and_transfer_entry /
# respond_tab_transfer, and core/receipt_views.py's receipt_respond_tab_transfer.

class SplitAndTransferEntryTest(TestCase):
    def setUp(self):
        self.biz = Business.objects.create(name='Split Transfer Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='split_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(username='split_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        Shift.objects.create(business=self.biz, staff=self.staff, status='OPEN')

        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Smirnoff',
            material_no='SPLIT-01', unit='Pcs', selling_price=Decimal('600'),
            cost_price=Decimal('300'),
        )

    def _make_tab(self, name, amount, desc='Smirnoff'):
        tab = BarTab.objects.create(business=self.biz, customer_name=name, status='OPEN', source='bar')
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=amount, payment_method='',
        )
        entry = BarTabEntry.objects.create(
            tab=tab, transaction=txn, description=desc, amount=amount, is_paid=False,
        )
        return tab, entry

    def test_split_creates_correct_paid_and_unpaid_amounts(self):
        roy_tab, entry = self._make_tab('Roy', Decimal('600'))
        bosco_tab, _bosco_entry = self._make_tab('Bosco', Decimal('50'))

        new_entry, tfr = BarTabEntry.split_and_transfer_locked(
            entry_id=entry.id, business=self.biz, paid_amount=Decimal('400'),
            paid_method='cash', dest_tab_id=bosco_tab.id, staff_user=self.staff,
        )
        entry.refresh_from_db()
        self.assertEqual(entry.amount, Decimal('400'))
        self.assertTrue(entry.is_paid)
        self.assertEqual(entry.payment_method, 'cash')
        self.assertEqual(new_entry.amount, Decimal('200'))
        self.assertFalse(new_entry.is_paid)
        self.assertEqual(
            new_entry.tab_id, roy_tab.id,
            'The remainder stays on the SOURCE tab until accepted — never on the destination yet',
        )
        self.assertEqual(tfr.status, 'PENDING')
        self.assertEqual(tfr.dest_tab_id, bosco_tab.id)

        # Total revenue for the Smirnoff sale must still be exactly 600 (400 + 200)
        # — no double count from the split.
        smirnoff_revenue = entry.transaction.revenue() + new_entry.transaction.revenue()
        self.assertEqual(smirnoff_revenue, 600.0)

    def test_split_rejects_paid_amount_equal_to_full_entry(self):
        _roy_tab, entry = self._make_tab('Roy', Decimal('600'))
        bosco_tab, _ = self._make_tab('Bosco', Decimal('50'))
        with self.assertRaises(ValueError):
            BarTabEntry.split_and_transfer_locked(
                entry_id=entry.id, business=self.biz, paid_amount=Decimal('600'),
                paid_method='cash', dest_tab_id=bosco_tab.id, staff_user=self.staff,
            )

    def test_accept_moves_entry_without_creating_new_transaction(self):
        roy_tab, entry = self._make_tab('Roy', Decimal('600'))
        bosco_tab, _ = self._make_tab('Bosco', Decimal('50'))
        new_entry, tfr = BarTabEntry.split_and_transfer_locked(
            entry_id=entry.id, business=self.biz, paid_amount=Decimal('400'),
            paid_method='cash', dest_tab_id=bosco_tab.id, staff_user=self.staff,
        )
        txn_count_before = Transaction.objects.filter(item=self.item).count()
        tfr.accept()
        new_entry.refresh_from_db()
        tfr.refresh_from_db()
        self.assertEqual(new_entry.tab_id, bosco_tab.id)
        self.assertEqual(tfr.status, 'ACCEPTED')
        self.assertEqual(
            Transaction.objects.filter(item=self.item).count(), txn_count_before,
            'accept() must be a pure tab_id reassignment — no new Transaction created',
        )
        entry.refresh_from_db()
        total_revenue = entry.transaction.revenue() + new_entry.transaction.revenue()
        self.assertEqual(total_revenue, 600.0)

    def test_reject_leaves_source_tab_completely_unchanged(self):
        roy_tab, entry = self._make_tab('Roy', Decimal('600'))
        bosco_tab, _ = self._make_tab('Bosco', Decimal('50'))
        new_entry, tfr = BarTabEntry.split_and_transfer_locked(
            entry_id=entry.id, business=self.biz, paid_amount=Decimal('400'),
            paid_method='cash', dest_tab_id=bosco_tab.id, staff_user=self.staff,
        )
        tfr.reject()
        new_entry.refresh_from_db()
        tfr.refresh_from_db()
        self.assertEqual(new_entry.tab_id, roy_tab.id, 'Never moved — nothing to reverse')
        self.assertFalse(new_entry.is_paid)
        self.assertEqual(tfr.status, 'REJECTED')
        self.assertEqual(roy_tab.unpaid_total(), Decimal('200'))

    def test_keg_item_split_does_not_double_increment_revenue_collected(self):
        barrel = KegBarrel.objects.create(
            business=self.biz, item=self.item, cost_price=Decimal('3000'),
            target_revenue=Decimal('6000'), revenue_collected=Decimal('600'),
        )
        roy_tab = BarTab.objects.create(business=self.biz, customer_name='Roy', status='OPEN', source='bar')
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-500'),
            sale_amount=Decimal('600'), keg_barrel=barrel, payment_method='',
        )
        entry = BarTabEntry.objects.create(
            tab=roy_tab, transaction=txn, description='Tusker', amount=Decimal('600'), is_paid=False,
        )
        bosco_tab, _ = self._make_tab('Bosco', Decimal('50'))

        new_entry, tfr = BarTabEntry.split_and_transfer_locked(
            entry_id=entry.id, business=self.biz, paid_amount=Decimal('400'),
            paid_method='cash', dest_tab_id=bosco_tab.id, staff_user=self.staff,
        )
        barrel.refresh_from_db()
        self.assertEqual(
            barrel.revenue_collected, Decimal('600'),
            'record_sale() must NOT be called again — revenue_collected was already correct',
        )
        entry.refresh_from_db()
        # Proportional cost across both halves must sum to the cost of the ORIGINAL
        # full 600 sale (sale_amount * cost_price / target_revenue), not more, not less.
        total_cost = entry.transaction.cost() + new_entry.transaction.cost()
        self.assertAlmostEqual(total_cost, 600 * 3000 / 6000, places=2)

    def test_station_scope_blocks_staff_without_access_to_source_tab(self):
        Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        kitchen_staff = User.objects.create_user(username='split_kstaff', password='x')
        UserProfile.objects.create(user=kitchen_staff, business=self.biz, role='kitchen', can_access_bar=False)
        Shift.objects.create(business=self.biz, staff=kitchen_staff, status='OPEN')

        _roy_tab, entry = self._make_tab('Roy', Decimal('600'))
        bosco_tab, _ = self._make_tab('Bosco', Decimal('50'))
        self.client.force_login(kitchen_staff)
        resp = self.client.post(f'/bar/tabs/entries/{entry.id}/split-transfer/', {
            'paid_amount': '400', 'paid_method': 'cash', 'dest_tab_id': bosco_tab.id,
        })
        self.assertEqual(resp.status_code, 404)

    def test_auto_cancel_pending_transfer_when_source_tab_voided(self):
        roy_tab, entry = self._make_tab('Roy', Decimal('600'))
        bosco_tab, _ = self._make_tab('Bosco', Decimal('50'))
